#include <domains/accelerators/inventory.hpp>
#include <algorithm>
#include <fstream>
namespace rebuntu::domains::gpu {static std::string read(const std::filesystem::path&p){std::ifstream f(p);std::string s;std::getline(f,s);return s;}std::vector<Device> Inventory::pci_devices()const{std::vector<Device>out;auto root=sys_/"bus/pci/devices";if(!std::filesystem::exists(root))return out;for(auto&e:std::filesystem::directory_iterator(root)){Device d;d.pci_address=e.path().filename();d.vendor_id=read(e.path()/"vendor");d.device_id=read(e.path()/"device");d.class_id=read(e.path()/"class");d.display_controller=d.class_id.rfind("0x03",0)==0;std::error_code ec;auto link=std::filesystem::read_symlink(e.path()/"driver",ec);if(!ec)d.driver=link.filename().string();out.push_back(std::move(d));}std::sort(out.begin(),out.end(),[](auto&a,auto&b){return a.pci_address<b.pci_address;});return out;}std::vector<Device>Inventory::display_devices()const{auto all=pci_devices();std::erase_if(all,[](auto&d){return !d.display_controller;});return all;}}
